mapper.select:
SELECT s.id, s.user_id, s.shop_name, s.province, s.city, s.detail_address, s.category, d1.enum_name AS category_name, s.description, s.avatar_url, s.contact_name, s.contact_phone, s.license_no, s.license_photo_url, s.license_expire_date, s.audit_status, d2.enum_name AS audit_status_name, s.audit_remark, s.audit_time, s.shop_status, d3.enum_name AS shop_status_name, s.create_time, s.update_time FROM otps_shop s LEFT JOIN otps_dict d1 ON d1.dict_id = 'shop:category' AND d1.enum_code = s.category LEFT JOIN otps_dict d2 ON d2.dict_id = 'shop:audit_status' AND d2.enum_code = s.audit_status LEFT JOIN otps_dict d3 ON d3.dict_id = 'shop:shop_status' AND d3.enum_code = s.shop_status
AND s.id = #{query.id}
AND s.user_id = #{query.userId}
AND s.shop_name LIKE '%' || #{query.shopName} || '%'
AND s.category = #{query.category}
AND s.audit_status = #{query.auditStatus}
AND s.shop_status = #{query.shopStatus}
AND s.province = #{query.province}
AND s.city = #{query.city}
ORDER BY s.create_time DESC
